const { test } = require('node:test');
const assert = require('node:assert');
const { addMonths } = require('./dates.js');

test('mid-month dates keep their day', () => {
  assert.strictEqual(addMonths(new Date(2026, 0, 15), 1).getTime(), new Date(2026, 1, 15).getTime());
});

test('Jan 31 + 1 month clamps to Feb 28 (not Mar 3)', () => {
  assert.strictEqual(addMonths(new Date(2026, 0, 31), 1).getTime(), new Date(2026, 1, 28).getTime());
});

test('Jan 31 + 1 month in a leap year clamps to Feb 29', () => {
  assert.strictEqual(addMonths(new Date(2028, 0, 31), 1).getTime(), new Date(2028, 1, 29).getTime());
});

test('31st into a 30-day month clamps to the 30th', () => {
  assert.strictEqual(addMonths(new Date(2026, 0, 31), 3).getTime(), new Date(2026, 3, 30).getTime());
});

test('Aug 31 + 1 month is Sep 30', () => {
  assert.strictEqual(addMonths(new Date(2026, 7, 31), 1).getTime(), new Date(2026, 8, 30).getTime());
});

test('negative offsets clamp too (Mar 31 - 1 month is Feb 28)', () => {
  assert.strictEqual(addMonths(new Date(2026, 2, 31), -1).getTime(), new Date(2026, 1, 28).getTime());
});

test('year rollover works (Nov 30 + 3 months is Feb 28 of next year)', () => {
  assert.strictEqual(addMonths(new Date(2026, 10, 30), 3).getTime(), new Date(2027, 1, 28).getTime());
});

test('keeps time of day and does not mutate the input', () => {
  const input = new Date(2026, 0, 31, 13, 45, 7, 250);
  const before = input.getTime();
  const out = addMonths(input, 1);
  assert.strictEqual(out.getTime(), new Date(2026, 1, 28, 13, 45, 7, 250).getTime());
  assert.strictEqual(input.getTime(), before);
});

